"""Shared helpers and verified example sentences (see scripts/generate_examples.py)."""
from __future__ import annotations


def checksum(body: str) -> str:
    value = 0
    for ch in body:
        value ^= ord(ch)
    return f"{value:02X}"


def make_sentence(body_fields: str) -> str:
    """Wrap 'AIVDM,1,1,,A,payload,0' style bodies with '!' and checksum."""
    return f"!{body_fields}*{checksum(body_fields)}"


